// Convert harvested JSON into importable ES modules (Worker-safe, no fs).
import fs from 'node:fs';
import path from 'node:path';

const root = path.join(path.dirname(new URL(import.meta.url).pathname), '..');
const read = f => JSON.parse(fs.readFileSync(path.join(root, 'src', 'data', f), 'utf8'));

const catalog = read('catalog.json');
const climate = read('climate.json');
const psi = read('psi-table.json');

fs.writeFileSync(path.join(root, 'src', 'data', 'catalog.js'),
  '// Generated by scripts/build-data.mjs from the live page + oracle probes.\nexport const CATALOG = ' + JSON.stringify(catalog) + ';\n');
fs.writeFileSync(path.join(root, 'src', 'data', 'climate.js'),
  '// Generated by scripts/build-data.mjs. QCVN 02:2022/BXD station normal values.\nexport const CLIMATE = ' + JSON.stringify(climate) + ';\n');
fs.writeFileSync(path.join(root, 'src', 'data', 'psi.js'),
  '// Generated by scripts/build-data.mjs. Bảng 2.10 – ψ(A_ttđ/A_tN, z).\nexport const PSI = ' + JSON.stringify(psi) + ';\n');
console.log('wrote catalog.js climate.js psi.js');
